    let cancelled = false;
    let pc = null;
    let localStream = null;
    let pollTimer = null;
    let lastSeenId = 0;
    let peerId = null;
    let role = null; // 'offerer' | 'answerer', decided once the peer's first message is seen
    let madeOffer = false;
    let remoteDescSet = false;
    let connected = false;
