  // unlocked: plaintext tables are not read afterwards.
  const applyVaultItems = (session, items, quarantined) => {
    const revMap = new Map();
    const papers = [], invs = [], cols = [];
    for (const row of items || []) {
      revMap.set(row.id, row.rev || 0);
      if (row.kind === "paper") {
        papers.push({ ...(row.payload || {}), collectionId: row.collectionId != null ? row.collectionId : (row.payload && row.payload.collectionId) || null, zkId: row.id, zkRev: row.rev || 0 });
      } else if (row.kind === "investigation") {
        invs.push({ ...(row.payload || {}), zkId: row.id, zkRev: row.rev || 0 });
      } else if (row.kind === "collection-meta") {
        cols.push({ id: row.id, name: (row.payload && row.payload.name) || "Collection", created_at: (row.payload && row.payload.createdAt) || row.updatedAt || Date.now(), zkId: row.id, zkRev: row.rev || 0 });
      }
    }
    zkRevRef.current = revMap;
    zkLastPushedIds.current = {
      saved: new Set(papers.map((p) => p.zkId)),
      history: new Set(invs.map((h) => h.zkId)),
    };
    // Seed content fingerprints from the pulled rows, normalized exactly
    // like the push path, so the first push after unlock doesn't
    // re-upload everything with bumped revs.
    const fp = new Map();
    for (const p of papers) fp.set(p.zkId, zkFingerprint({ kind: "paper", collectionId: p.collectionId || null, payload: zkPaperPayload(p) }));
    for (const h of invs) fp.set(h.zkId, zkFingerprint({ kind: "investigation", collectionId: null, payload: zkInvPayload(h) }));
    zkFpRef.current = fp;
    setSaved(papers);
    setHistory(invs);
    setCollections(cols);
    if (quarantined && quarantined.length) {
      toast(`Skipped ${quarantined.length} item${quarantined.length === 1 ? "" : "s"} that couldn't be decrypted.`, { tone: "error" });
    }
  };
  const zkVaultExists = (vs) => !!(vs && (vs.exists || vs.dekId || vs.dek_id || vs.wrappedDek || vs.wrapped_dek));
  // Runs after the legacy pulls in handleAuthed. If the account has a
  // vault row it takes over: unlocked when the recovery phrase is on
  // this device, locked (sync paused, never plaintext) otherwise.
  const initVaultForUser = async (authedUser, legacy = {}) => {
    vaultTransitionRef.current = true;
    zkSessionRef.current = null;
    zkRevRef.current = new Map();
    zkLastPushedIds.current = { saved: new Set(), history: new Set() };
    zkFpRef.current = new Map();
    setVaultMode("off");
    setVaultMigPending(false);
    // Locked means nothing decrypted is shown. The legacy plaintext that
    // handleAuthed just pulled must not linger in the UI or in plaintext
    // localStorage — sync pauses, fail-closed, never plaintext.
    const clearForLocked = () => {
      setSaved([]);
      setHistory([]);
      setCollections([]);
      try { localStorage.removeItem("cb_saved"); } catch {}
      try { localStorage.removeItem("cb_history"); } catch {}
      setImportPrompt(null);
    };
    try {
      const uid = authedUser && authedUser.id;
      if (!uid) return;
      let session = null;
      try {
        session = new ZkSession({ userId: uid, post: zkPost, getPhrase: getRecoveryPhrase });
      } catch { return; }
      const vs = await session.getVaultState().catch(() => null);
      if (!zkVaultExists(vs)) return;
      // A vault exists: any guest import prompt is moot — the vault, not
      // the browser's guest data, is this account's library.
      setImportPrompt(null);
      const phrase = await getRecoveryPhrase().catch(() => null);
      if (!phrase) {
        zkSessionRef.current = session;
        clearForLocked();
        setVaultMode("locked");
        toast("Private Vault is locked on this device — confirm your recovery phrase in Settings to resume syncing.");
        return;
      }
      try {
        await session.unlock(phrase);
        const pulled = await session.pullItems();
        zkSessionRef.current = session;
        if ((pulled.items || []).length === 0 && ((legacy.saved || 0) > 0 || (legacy.history || 0) > 0)) {
          // Half-finished migration: the vault row exists but the
          // encrypted upload never completed. Keep the legacy library
          // visible (it's the user's data, shown exactly as it was) and
          // offer "Finish turning on Private Vault" in Settings. Never
          // silently replace a real library with an empty vault.
          setVaultMode("locked");
          setVaultMigPending(true);
          toast("Private Vault wasn't finished turning on. Finish it in Settings to move your library into the vault.");
        } else {
          applyVaultItems(session, pulled.items, pulled.quarantined);
          setVaultMode("unlocked");
        }
      } catch (e) {
        zkSessionRef.current = session;
        clearForLocked();
        setVaultMode("locked");
        toast("Private Vault is locked on this device — confirm your recovery phrase in Settings to resume syncing.");
      }
    } finally {
      vaultTransitionRef.current = false;
    }
  };

  /* New-version detection: compare the baked-in build SHA (__CB_BUILD__,
     vite.config.js) against the freshly-served public/version.json every
     10 minutes. The banner shows only while idle — a deploy landing
     mid-search must not interrupt the investigation. If a mismatch is seen
     while busy, it surfaces once the search settles. */
  const [updateReady, setUpdateReady] = useState(false);
  const busyRef = useRef(busy);
  busyRef.current = busy;
  const updateSeenRef = useRef(false);
  useEffect(() => {
    let alive = true;
    const check = async () => {
      try {
        const r = await fetch("/version.json", { cache: "no-store" });
        if (!r.ok) return;
        const j = await r.json();
        const current = typeof __CB_BUILD__ !== "undefined" ? __CB_BUILD__ : "dev";
        if (j && j.sha && j.sha !== current) {
          updateSeenRef.current = true;
          if (!busyRef.current && alive) setUpdateReady(true);
        }
      } catch { /* offline, or a build predating version.json — stay silent */ }
    };
    check();
    const id = setInterval(check, 10 * 60 * 1000);
    return () => { alive = false; clearInterval(id); };
  }, []);
  useEffect(() => {
    if (!busy && updateSeenRef.current) setUpdateReady(true);
  }, [busy]);

  /* Commit 88 — these derive from `history` and `saved`, so they must be
     declared after both. Placing them next to confirmClearSaved (which is
     above the `saved` useState) put `saved` in its own temporal dead zone
     and the whole app threw on mount. */
  const [historyQuery, setHistoryQuery] = useState("");
  /* Private Vault local search: when unlocked, both search boxes query
     the decrypted on-device index (queryLocalIndex) — search terms never
     leave the device and nothing is sent server-side. The index rebuilds
     only when the underlying lists change, not per keystroke. Items that
     somehow lack a vault id fall back to the plain local filter, which is
     still fully on-device. */
  const zkIndexReady = useMemo(() => {
    if (vaultMode !== "unlocked") return false;
    const session = zkSessionRef.current;
    if (!session || typeof session.buildLocalIndex !== "function") return false;
    try {
      const rows = [
        ...(saved || []).map((s) => ({ id: s.zkId || makeItemId("paper"), kind: "paper", collectionId: s.collectionId || null, payload: zkPaperPayload(s), rev: zkRevRef.current.get(s.zkId) || 0 })),
        ...(history || []).map((h) => ({ id: h.zkId || h.id || makeItemId("inv"), kind: "investigation", collectionId: null, payload: zkInvPayload(h), rev: zkRevRef.current.get(h.zkId) || 0 })),
      ];
      // buildLocalIndex may take rows or read the session's own decrypted
      // store; the arity check picks the right call shape.
      if (session.buildLocalIndex.length > 0) session.buildLocalIndex(rows);
      else session.buildLocalIndex();
      return true;
    } catch { return false; }
  }, [saved, history, vaultMode]);
  const zkQueryIds = (q) => {
    if (!zkIndexReady) return null;
    const session = zkSessionRef.current;
    if (!session || typeof session.queryLocalIndex !== "function") return null;
    try {
      const res = session.queryLocalIndex(q) || [];
      const ids = new Set();
      for (const r of res) {
        const id = typeof r === "string" ? r : (r && (r.id || r.zkId));
        if (id) ids.add(id);
      }
      return ids;
    } catch { return null; }
  };
  // One bundle handed to the Settings "Private Vault" section: everything
  // the ceremony needs, without prop-drilling a dozen callbacks.
  const vaultCtl = {
    mode: vaultMode,
    setMode: setVaultMode,
    getSession: () => zkSessionRef.current,
    setSession: (s) => { zkSessionRef.current = s; },
    post: zkPost,
    applyItems: applyVaultItems,
    nextRev: zkNextRev,
    lockAll: zkLockNow,
    holdLegacy: (on) => { vaultTransitionRef.current = on; },
    seedPushed: (savedIds, historyIds) => { zkLastPushedIds.current = { saved: new Set(savedIds), history: new Set(historyIds) }; },
    migPending: vaultMigPending,
    setMigPending: setVaultMigPending,
    localOnly: vaultLocalOnly,
    setLocalOnly: setVaultLocalOnly,
    isLocalOnly: () => vaultLocalOnlyRef.current,
    pushBatched: zkPushBatched,
    errorMessage: zkErrorMessage,
    paperPayload: zkPaperPayload,
    invPayload: zkInvPayload,
    colPayload: zkColPayload,
    writeBackSaved: (rows) => setSaved((prev) => zkWriteBack(prev, rows)),
    writeBackHistory: (rows) => setHistory((prev) => zkWriteBack(prev, rows)),
    writeBackCollections: (rows) => setCollections((prev) => {
      if (!Array.isArray(prev) || prev.length !== rows.length) return prev;
      let changed = false;
      const next = prev.map((c, i) => {
        const r = rows[i];
        if (!r || c.id !== r.id || c.zkRev === r.rev) return c;
        changed = true;
        return { ...c, zkRev: r.rev };
      });
      return changed ? next : prev;
    }),
  };


  const visibleHistory = useMemo(() => {
    const q = historyQuery.trim();
    if (!q) return history;
    const ql = q.toLowerCase();
    const legacyMatch = (h) => String(h.title || "").toLowerCase().includes(ql)
      || (h.turns || []).some((t) => String(t.q || "").toLowerCase().includes(ql));
    const ids = zkQueryIds(q);
    if (!ids) return history.filter(legacyMatch);
    return history.filter((h) => (h.zkId ? ids.has(h.zkId) : legacyMatch(h)));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [history, historyQuery, zkIndexReady]);
  /* Investigations grouped by month for the diary view: [{ key, label,
     items }], newest month first. Items without a timestamp land in
     "Earlier". */
  const groupedHistory = useMemo(() => {
    const groups = new Map();
    for (const h of visibleHistory) {
      const d = h.ts ? new Date(h.ts) : null;
      const key = d && !isNaN(d) ? `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}` : "earlier";
      const label = key === "earlier" ? "Earlier" : d.toLocaleDateString(undefined, { month: "long", year: "numeric" });
      if (!groups.has(key)) groups.set(key, { key, label, items: [] });
      groups.get(key).items.push(h);
    }
    return [...groups.values()].sort((a, b) => b.key.localeCompare(a.key));
  }, [visibleHistory]);
  const [libraryQuery, setLibraryQuery] = useState("");
  const [librarySort, setLibrarySort] = useState("recent");
  /* Library bulk selection: a Set of sourceKeys. Powers the bulk bar
     (export selected, move to collection, remove selected). Cleared
     whenever the underlying list changes shape. */
  const [selectedSavedKeys, setSelectedSavedKeys] = useState(() => new Set());
  const toggleSavedKey = (key) => setSelectedSavedKeys((prev) => {
    const next = new Set(prev); if (next.has(key)) next.delete(key); else next.add(key); return next;
  });
  const visibleSaved = useMemo(() => {
    const q = libraryQuery.trim();
    let list;
    if (!q) {
      list = saved.slice();
    } else {
      const ql = q.toLowerCase();
      const legacyMatch = (sv) => [sv.title, sv.authors, sv.journal].filter(Boolean).join(" ").toLowerCase().includes(ql);
      const ids = zkQueryIds(q);
      list = ids
        ? saved.filter((sv) => (sv.zkId ? ids.has(sv.zkId) : legacyMatch(sv)))
        : saved.filter(legacyMatch);
    }
    if (librarySort === "title") return list.sort((x, y) => String(x.title || "").localeCompare(String(y.title || "")));
    if (librarySort === "year") return list.sort((x, y) => (Number(y.year) || 0) - (Number(x.year) || 0));
    // "recent" = when YOU saved it. savedAt was added in Commit 67; anything
    // predating that falls back to createdAt so old libraries still order.
    return list.sort((x, y) => (y.savedAt || y.createdAt || 0) - (x.savedAt || x.createdAt || 0));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [saved, libraryQuery, librarySort, zkIndexReady]);

  const [sessions, setSessions] = useState([]);
  const [mobilePanel, setMobilePanel] = useState(false);
  const [suggestions, setSuggestions] = useState(pick());
  /* Chosen once per mount, not per render — a line that reshuffled every
     time React re-rendered would flicker while you type. */
  const [composerPrompt] = useState(() => COMPOSER_PROMPTS[Math.floor(Math.random() * COMPOSER_PROMPTS.length)]);
  const chipsPausedRef = useRef(false);
  const [settingsInitialTab, setSettingsInitialTab] = useState("answers");
  const [drawerSource, setDrawerSource] = useState(null);
  const [focusedSourceIdx, setFocusedSourceIdx] = useState(-1);
  const [evidenceFilter, setEvidenceFilter] = useState("all");
  /* Commit 83 — the instrument's operations.
     `askMode` is the verb the person picked on the welcome screen. It is
     sent with the query and changes the SHAPE of the answer server-side
     (see MODE_STRUCTURES in functions/api/search.js), not just the
     wording of the prompt — "compare" returns a comparison, "verify"
     returns a verdict. A chatbot has one output shape; this is what
     having more than one looks like. */
  const [askMode, setAskMode] = useState("explain");
  const [evidenceScrollRef, evidenceMask] = useEdgeMask();
  const [dataDensity, setDataDensity] = useState(() => getCookie("cb_density") || "comfortable");
  const [cmdOpen, setCmdOpen] = useState(false);
  const [cmdQuery, setCmdQuery] = useState("");
  const [zoteroOpen, setZoteroOpen] = useState(false);
  const [srcSort, setSrcSort] = useState("relevance");
  const [srcFilter, setSrcFilter] = useState("");
  const [zKey, setZKey] = useState(""); const [zUser, setZUser] = useState(""); const [zMsg, setZMsg] = useState("");
  const [answerLength, setAnswerLength] = useState(() => getCookie("cb_len") || "medium");
  const [factCheck, setFactCheck] = useState(true);
  const [muted, setMuted] = useState(() => getCookie("cb_muted") === "1");
  const [soundMode, setSoundMode] = useState(() => getCookie("cb_snd") || "pulse");
  const [typewriter, setTypewriter] = useState(() => getCookie("cb_tw") !== "0");
  const [citationStyle, setCitationStyle] = useState(() => getCookie("cb_cite") || "vancouver");
  // v6.6: this used to default every first-time visitor into "cinematic" —
  // a continuously-rendering CDN-loaded WebGL scene (Vanta.js/three.js, long
  // since replaced — see LivingBackground's own comment) running behind a
  // page that ALSO leans hard on `backdrop-filter: blur(...)` for the
  // header, answer card, search bar, and chips. Those two together were a
  // well-known perf collision: every frame the WebGL canvas changed, every
  // blurred element sitting over it had to recompute its blur from scratch,
  // continuously, whether or not anyone was even scrolling — and it lined up
  // with a real, repeated report of laggy, unresponsive wheel-scroll that
  // only a scrollbar drag could get past. LivingBackground is now a plain,
  // much cheaper 2D canvas with no continuous GPU scene behind it, but the
  // CSS-only `ambient` wash (see makeStyles) already gives every visitor a
  // real sense of depth/atmosphere at effectively zero cost regardless, so
  // there's no reason to default animation on for everyone — it stays one
  // click away in Settings → Appearance for anyone who wants it.
  // v29: this defaulted to "off", which meant the ENTIRE WebGL background
  // system built across the last several commits (WebGLFluidRipples,
  // VantaCellsField, WebGLNeuralField) never actually rendered for a first-
  // time visitor — the only thing they ever saw was the static `.cb-ambient`
  // gradient wash underneath it. That's the real root cause behind "the
  // background looks cloudy, not tech": there was no WebGL on screen to look
  // sharp OR cloudy, just the blur. Flipped to "cinematic" so the
  // (now-brightened) WebGL layer is what a new visitor actually sees.
  // `prefers-reduced-motion` still overrides this per-component (each WebGL
  // field checks it independently), so this doesn't fight accessibility —
  // it only changes what people who haven't opted out of motion get by
  // default. Respects an explicit stored preference either way.
  const [animationMode, setAnimationMode] = useState(() => getCookie("cb_anim2") || "cinematic");
  // v5: this used to swap the chip row's content out from under the user
  // every 8s unconditionally — a real interaction hazard, not just a CSS
  // animation, since a keyboard user who tabs to a chip and takes >8s to
  // decide would submit a DIFFERENT question than the one they read. Pause
  // while any chip has hover or focus, and don't rotate at all when the
  // user has turned animations off in Settings. (This effect has to live
  // down here, after animationMode's own declaration — its dependency array
  // reads that binding, and a dependency array is evaluated eagerly on every
  // render, unlike the effect body itself; declaring it any earlier in the
  // component would be reading `animationMode` before its own `const` runs.)
  useEffect(() => {
    if (turns.length > 0 || animationMode === "off") return;
    const id = setInterval(() => { if (!chipsPausedRef.current) setSuggestions(pick()); }, 8000);
    return () => clearInterval(id);
  }, [turns.length, animationMode]);
  // Bug: three independent binary Switches (General>Motion "Background
  // effects", General>Motion "Reduced motion", Accessibility>Motion "Reduce
  // motion") used to each control this same 3-way ("off"|"subtle"|
  // "cinematic") value, but each only recognized two of the three states —
  // so enabling one could silently clobber a choice made via another. E.g.
  // Accessibility's "Reduce motion" (→"off") looked unchanged/unchecked on
  // General's "Reduced motion" switch, and toggling THAT switch set the
  // mode back to "subtle", silently re-enabling the animation the user had
  // just turned off. Fixed by making General's motion control a single
  // 3-way Picker (one authoritative control, no lossy binary projections),
  // and having Accessibility's on/off shortcut restore the user's last
  // non-off choice instead of hardcoding "cinematic" — tracked here.
  const lastAnimModeRef = useRef(animationMode !== "off" ? animationMode : "cinematic");
  useEffect(() => { if (animationMode !== "off") lastAnimModeRef.current = animationMode; }, [animationMode]);
  // v6.9: this used to also carry animPreset/animDensity/animOpacity —
  // three more pieces of persisted state, threaded all the way through
  // Settings' props and into LivingBackground, with no Settings control
  // that ever actually let a user change any of them (no onChange/setter
  // call site existed anywhere in the file besides these useState
  // initializers), AND LivingBackground's own render logic never read
  // `preset` or `opacity` at all and only used `density` in a dependency
  // array with no effect on what it computed. Pure dead weight — removed.
  // `animSpeed` is the one that actually does something (LivingBackground
  // scales the ConstellationField's drift speed by it), so it's kept, and
  // now has a real control below instead of being permanently stuck at its
  // default.
  const [animSpeed, setAnimSpeed] = useState(() => parseFloat(getCookie("cb_animS") || "1"));
  // v31: the per-screen background STYLE choice (bgStyleIntro/bgStyleMain,
  // and the four components it picked between) is retired — Intro and the
  // main app shell each get one fixed, dedicated field now (Orb / SoftAurora,
